function getIcon(name) { return ICONS[name] || ICONS.shield; }

// ── Empty-state picker — chooses 5–6 contextually relevant topics ──

export function pickEmptyStateSuggestions({ activeIncident = false, returning = false } = {}) {
  // Highest priority: active emergency. Don't bury the 911-adjacent CTAs.
  if (activeIncident) {
    return [
      { icon: 'shield', label: "What should I do right now?",     prompt: "There's an active emergency in my area. What's the safest first step?" },
      { icon: 'pin',    label: "Where do I evacuate?",            prompt: "How do I find my evacuation route from my Poway address?" },
      { icon: 'phone',  label: "Reach my Neighborhood Coordinator", prompt: "How do I reach my Neighborhood Emergency Coordinator (NEC) right now?" },
      { icon: 'bell',   label: "Today's Poway risk",              prompt: "What's the current wildfire / weather risk in Poway right now?" },
      { icon: 'radio',  label: "If cell service is down",         prompt: "What if cell service is down during this emergency — how do I get info?" },
    ];
  }

  // Admin: prep tools, not preparedness questions
  const user = getCachedUser();
  if (user && user.role === 'admin') return ADMIN_TOPICS;

  // Returning user: less onboarding, more "what's next"
  if (returning) {
    return [
      { icon: 'spark',  label: "Continue where I left off",       prompt: "Pick up where we left off in my preparedness journey — what's next for me?" },
      { icon: 'kit',    label: "Check on my kit",                 prompt: "Help me update my emergency kit checklist." },
      { icon: 'event',  label: "Upcoming events",                 prompt: "What PNEC events or drills are coming up I should know about?" },
      { icon: 'flame',  label: "Home Ignition Zone Assessment",   prompt: "What's a Home Ignition Zone Assessment and how do I sign up?" },
      { icon: 'badge',  label: "Join Poway CERT",                 prompt: "How do I join Poway CERT? What are the requirements?" },
      { icon: 'heart',  label: "Donate to PNEC",                  prompt: "How do I donate to PNEC?" },
    ];
  }

  // Fire-season default (May–Oct in Poway): heavy fire weighting
  const month = new Date().getMonth() + 1;
  if (month >= 5 && month <= 10) {
    return [
      { icon: 'flame',  label: "Make my home fire-safer this weekend", prompt: "What's the most impactful thing I can do this weekend to reduce wildfire risk on my property?" },
      { icon: 'flame',  label: "What is Zone Zero?",              prompt: "Explain what 'Zone Zero' means around my house and what I'm supposed to do in that zone." },
      { icon: 'pin',    label: "Find my evacuation route",        prompt: "How do I find my evacuation route from my Poway address?" },
      { icon: 'kit',    label: "Check my emergency kit",          prompt: "What should be in my 72-hour kit and how do I check it's still good?" },
      { icon: 'people', label: "Find my Neighborhood Coordinator", prompt: "How do I find out who my Neighborhood Emergency Coordinator (NEC) is?" },
      { icon: 'event',  label: "Next Safety Fair",                prompt: "When and where is the next Annual Emergency & Safety Fair?" },
    ];
  }

  // Cool-season default (Nov–Apr): year-round prep + earthquake
  return [
    { icon: 'kit',    label: "Build a 72-hour kit",               prompt: "Walk me through building a 72-hour kit from scratch — checklist and budget." },
    { icon: 'shield', label: "Earthquake prep basics",            prompt: "What are the top 3 things I should do this week to be earthquake-ready?" },
    { icon: 'people', label: "Find my Neighborhood Coordinator",   prompt: "How do I find out who my Neighborhood Emergency Coordinator (NEC) is?" },
    { icon: 'badge',  label: "Join Poway CERT",                   prompt: "How do I join Poway CERT? What are the requirements?" },
    { icon: 'event',  label: "Next event or drill",               prompt: "What PNEC events, drills, or trainings are coming up I can attend?" },
    { icon: 'hands',  label: "Volunteer with PNEC",               prompt: "How can I volunteer with PNEC? What are the time commitments?" },
  ];
}

// ── Render: empty-state list of chips ───────────────────────────

export function renderSuggestionList(container, suggestions, onPick) {
  container.innerHTML = '';
  suggestions.forEach(s => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'pnec-bot-suggestion';
    btn.dataset.prompt = s.prompt;
    btn.innerHTML = `
      <span class="pnec-bot-suggestion-icon">${getIcon(s.icon)}</span>
      <span class="pnec-bot-suggestion-text">${s.label}</span>
      <span class="pnec-bot-suggestion-arrow">
        <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg>
      </span>
    `;
    btn.addEventListener('click', () => onPick(s.prompt));
    container.appendChild(btn);
  });
}

// ── Render: full categorized topic library ──────────────────────
// Used by the "Browse all topics" expander. Renders every topic
// grouped by category, with the category label as a subtle header.

export function renderAllTopics(container, onPick) {
  container.innerHTML = '';
  Object.entries(TOPICS).forEach(([key, group]) => {
    const section = document.createElement('div');
    section.className = 'pnec-bot-topics-group';
    const head = document.createElement('div');
    head.className = 'pnec-bot-topics-group-head';
    head.textContent = group.label;
    section.appendChild(head);

    group.items.forEach(s => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'pnec-bot-topic';
      btn.innerHTML = `
        <span class="pnec-bot-topic-icon">${getIcon(s.icon)}</span>
        <span class="pnec-bot-topic-text">${s.label}</span>
      `;
      btn.addEventListener('click', () => onPick(s.prompt));
      section.appendChild(btn);
    });

    container.appendChild(section);
  });
}

// Total count for the "Browse N topics" label
export function totalTopicCount() {
  return Object.values(TOPICS).reduce((sum, g) => sum + g.items.length, 0);
}

// ── Render: post-turn followup chips (LLM-generated) ────────────

export function renderFollowupChips(container, chips, onPick) {
  container.innerHTML = '';
  if (!chips.length) { container.hidden = true; return; }
  container.hidden = false;
  chips.forEach(text => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'pnec-bot-followup';
    btn.textContent = text;
    btn.addEventListener('click', () => onPick(text));
    container.appendChild(btn);
  });
}
